//! Cargo-driven `mstsc.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is mstsc-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/base/applications/mstsc",
        "base/applications/mstsc",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "vendor/rdesktop",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "WITH_SSL",
        "_CRT_NON_CONFORMING_SWPRINTFS",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
    ];

    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_wWinMainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "wWinMainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "wWinMainCRTStartup"),
        o => panic!("mstsc-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "import:user32", "import:gdi32", "import:comctl32", "import:ws2_32", "import:crypt32", "import:secur32", "import:advapi32", "import:shell32", "import:ole32", "import:comdlg32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        "x86_64" => &["body", "import:user32", "import:gdi32", "import:comctl32", "import:ws2_32", "import:crypt32", "import:secur32", "import:advapi32", "import:shell32", "import:ole32", "import:comdlg32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        "aarch64" => &["body", "import:user32", "import:gdi32", "import:comctl32", "import:ws2_32", "import:crypt32", "import:secur32", "import:advapi32", "import:shell32", "import:ole32", "import:comdlg32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("mstsc-rust")
        .c_from_compile_db("mstsc_shims", &["vendor/rdesktop/asn.c", "vendor/rdesktop/bitmap.c", "vendor/rdesktop/bsops.c", "vendor/rdesktop/cache.c", "vendor/rdesktop/channels.c", "vendor/rdesktop/iso.c", "vendor/rdesktop/licence.c", "vendor/rdesktop/mcs.c", "vendor/rdesktop/mppc.c", "vendor/rdesktop/orders.c", "vendor/rdesktop/pstcache.c", "vendor/rdesktop/rdp5.c", "vendor/rdesktop/rdp.c", "vendor/rdesktop/secure.c", "vendor/rdesktop/ssl_calls.c", "vendor/rdesktop/tcp.c", "vendor/rdesktop/uimain.c", "vendor/rdesktop/win32.c"])
        .rc("base/applications/mstsc/rdc.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/crypt32/crypt32.spec", "crypt32.dll", "crypt32")
        .import_lib("dll/win32/secur32/secur32.spec", "secur32.dll", "secur32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/comdlg32/comdlg32.spec", "comdlg32.dll", "comdlg32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::ExeWide)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "windows:5.01".into(),
        });
}
